const offline=offlineEarnings(state);let cells=[],scene,controls,automation,clock=0,lastFrame=0,active=true,harvestClock=0,uiClock=0,saveClock=0,checkClock=0,saleClock=0,saleCarry=0,saleRate=28,saleTotal=0,productSaleClock=0,lastBagWarn=-20,audioCtx,selectedTab='tools',modalView='',isSelling=false,lastHarvest=-10,combo=0,pads=[],padDwell=0,dwellingID='',completedPad='',padEffectClock=0,storageWarned=false,collectingRaw=false;
const player={...WORLD.spawn,angle:0,moving:false},floaters=[];
