const title=(eyebrow,heading,lead='')=>`<div class="modal-eyebrow">${eyebrow}</div><h2 class="modal-title">${heading}</h2>${lead?`<p class="modal-lead">${lead}</p>`:''}`;
function toast(message,gold=false){const el=document.createElement('div');el.className='toast'+(gold?' gold':'');el.textContent=message;$('toasts').append(el);while($('toasts').childElementCount>2)$('toasts').firstElementChild.remove();setTimeout(()=>el.remove(),4400);}
function sound(type='harvest'){if(!state.sound)return;try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();const o=audioCtx.createOscillator(),g=audioCtx.createGain(),t=audioCtx.currentTime,base=type==='sale'?880:type==='build'?440:660;o.type='sine';o.frequency.setValueAtTime(base*(type==='harvest'?[1,1.125,1.25,1.5][combo%4]:1),t);o.frequency.exponentialRampToValueAtTime(base*(type==='build'?2:1.3),t+.15);g.gain.setValueAtTime(type==='harvest'?.018:.03,t);g.gain.exponentialRampToValueAtTime(.001,t+.2);o.connect(g);g.connect(audioCtx.destination);o.start();o.stop(t+.21);}catch{}}
function save(){state.savedAt=Date.now();state.village.fieldCuts=Object.fromEntries(cells.filter(c=>c.readyAt>state.journey.growthTime).map(c=>[c.key,{cutAt:c.cutAt,readyAt:c.readyAt}]));automation?.snapshot?.(state);try{localStorage.setItem(storageKey,JSON.stringify(state));storageOK=true;}catch{storageOK=false;}$('saveStatus').innerHTML=storageOK?'<i></i> Gespeichert':'Speicher nicht verfügbar';}
function floater(x,z,text,rare=false){const el=document.createElement('div');el.className='harvest-floater'+(rare?' rare':'');el.textContent=text;$('floaters').append(el);floaters.push({el,x,z,y:2.3,life:1.25});while(floaters.length>14)floaters.shift().el.remove();}
function resetWorld(){prepareDay(state,TOOLS);cells=createVillageField(state);player.x=WORLD.spawn.x;player.z=WORLD.spawn.z;controls?.stop();automation=new GardenAutomation(state);pads=getBuildPads(state,TOOLS);scene?.build(cells,0,{state,toolDefs:TOOLS});completedPad='';syncUI();}
function refreshWorld(structural=false){pads=getBuildPads(state,TOOLS);if(structural){const focus=scene.focus.clone();cells=createVillageField(state,cells);scene.build(cells,0,{state,toolDefs:TOOLS});scene.focus.copy(focus);}else scene.refreshConstruction(state,TOOLS);automation.sync(state);syncUI();}
function closeModal(){if(modal.open)modal.close();modalView='';}
function openModal(html,view=''){controls?.stop();harvestClock=0;for(const cell of cells)cell.pickProgress=0;modalView=view;$('modalBody').innerHTML=html;if(!modal.open)modal.showModal();}
function walkTo(target){closeModal();if(controls)controls.target={x:target.x,z:target.z};}
function goBank(){walkTo(WORLD.bank);}
function goWarehouse(){walkTo({x:VILLAGE.warehouse.x,z:VILLAGE.warehouse.z+.7});}
function goPad(id){const pad=getBuildPads(state,TOOLS).find(p=>p.id===id);if(!pad||pad.max)return;if(pad.locked){toast(pad.reason);return;}walkTo(pad);toast('Auf der markierten Fläche stehen bleiben: '+pad.label+'.');}
$('sell').onclick=goBank;$('warehouse').onclick=goWarehouse;$('zoomIn').onclick=()=>scene?.setZoom(.1);$('zoomOut').onclick=()=>scene?.setZoom(-.1);
function tutorial(step){state.tutorial=step;const el=$('tutorial');el.hidden=step>=3;if(step===1){el.querySelector('span').textContent='EIN BÜNDEL NACH DEM ANDEREN';el.querySelector('h1').textContent='Das wird ein schöner Stapel.';el.querySelector('p').textContent='Zieht eure Bahnen durchs Beet. Die Ernte fliegt automatisch auf deinen Rücken.';}if(step===2){el.querySelector('span').textContent='VERKAUFEN ODER VEREDELN';el.querySelector('h1').textContent='Was wird aus euren Blumen?';el.querySelector('p').textContent='Verkaufe die Ernte am Stand oder bringe passende Zutaten links zur Werkstatt. Fertige Stapel holst du rechts ab.';}}
$('dismissTutorial').onclick=()=>{tutorial(3);save();};$('missionToggle').onclick=()=>$('missionWidget').classList.toggle('collapsed');
$('claimMission').onclick=()=>{const reward=claimMission(state);if(reward){toast('Sternenauftrag erfüllt: + '+format(reward)+' ✧.',true);sound('sale');syncUI();save();}};

function update(dt){clock+=dt;advanceLighting(state,dt);$('nightVeil').style.opacity=Math.max(0,(state.journey.light-.58)/.42)*.65;let simDt=modal.open||state.journey.asleep?0:dt;if(modal.open&&modalView==='farm'&&!state.journey.asleep)advanceFarm(state,dt);if(simDt){tickJourney(state,simDt);const rhythm=advanceDayRhythm(state);if(rhythm?.kind==='warning')toast('Du wirst müde: In '+Math.ceil(rhythm.seconds/60)+' Minuten schläfst du ein. '+(state.journey.closed?'Deine Pflanzenbelohnung ist schon gesichert.':'Sichere vorher deine Pflanzenbelohnung!'),true);if(rhythm?.kind==='sleep'){simDt=0;player.moving=false;controls.stop();save();refreshWorld(false);openSleep();}}const growthTime=state.journey.growthTime;state.stats.playSeconds+=simDt;const direction=controls.direction(player),speed=moveSpeed(state)/38;player.moving=!!(direction.x||direction.z);if(player.moving){player.x+=direction.x*speed*dt;player.z+=direction.z*speed*dt;clampWorld(player);let a=Math.atan2(direction.x,direction.z);while(a-player.angle>Math.PI)a-=Math.PI*2;while(a-player.angle<-Math.PI)a+=Math.PI*2;player.angle=a;if(state.tutorial===0)tutorial(1);}
  harvestClock+=simDt;if(harvestClock>=harvestRate(state)&&!modal.open&&!inBank(player.x,player.z)){
    const harvestDt=harvestClock;harvestClock=0;const picks=harvestAt(state,cells,player.x,player.z,growthTime,1,{moving:player.moving,dt:harvestDt});if(picks.length){farmHarvest+=picks.reduce((sum,p)=>sum+p.units,0);combo=clock-lastHarvest<1.1?combo+picks.length:picks.length;lastHarvest=clock;sound();scene.harvestFlash(player.x,player.z);picks.slice(0,3).forEach(p=>scene.makePickup(p.cell,p.rare));if(picks.some(p=>p.rare))floater(player.x,player.z,'Seltener Fund! ✧',true);if(state.tutorial<2&&state.bag>=capacity(state)*.65)tutorial(2);}
    if(state.bag>=capacity(state)&&clock-lastBagWarn>24){lastBagWarn=clock;toast('Dein Stapel ist voll. Verkaufen oder Zutaten zur Werkstatt bringen.');}
  }
  const atBank=inBank(player.x,player.z),atWarehouse=Math.hypot(player.x-VILLAGE.warehouse.x,player.z-VILLAGE.warehouse.z)<VILLAGE.warehouse.radius;
  if(simDt&&atBank&&state.bag>0){if(!isSelling){isSelling=true;saleRate=Math.max(28,state.bag/1.3);saleCarry=0;saleTotal=0;saleClock=0;}saleCarry+=dt*saleRate;saleClock+=dt;if(saleCarry>=2||state.bag<=saleCarry){const result=unload(state,Math.min(state.bag,Math.floor(saleCarry)));saleCarry-=result.units;saleTotal+=result.value;scene.receiveMoney(player,result.value);if(saleClock>.13){scene.makeSale(player);sound('sale');saleClock=0;}if(!state.bag){floater(WORLD.bank.x,WORLD.bank.z,'+ '+format(saleTotal)+' ✧');if(state.tutorial<3){tutorial(3);toast('Ernte verkauft. Kaufe Verbesserungen, indem du auf den ↑-Flächen stehen bleibst.');}save();}}}else{isSelling=false;saleCarry=0;}
  productSaleClock+=simDt;if(simDt&&atBank&&productSaleClock>.7){productSaleClock=0;const batch=sellCarriedProducts(state);if(batch.count){scene.receiveMoney(player,batch.value);floater(WORLD.bank.x,WORLD.bank.z,'Produkte + '+format(batch.value)+' ✧');sound('sale');scene.makeSale(player);}}
  if(simDt&&atWarehouse&&collectingRaw){const batch=withdrawBag(state,capacity(state)-state.bag-productCargoCount(state));collectingRaw=false;if(batch.count)goBank();else toast('Keine Rohstoffe zum Abholen.');}else if(simDt&&atWarehouse&&!player.moving&&state.bag>0){const batch=depositBag(state,Math.max(1,Math.floor(dt*90)));if(batch.count){scene.makeTransfer(player,VILLAGE.warehouse);if(state.tutorial<3)tutorial(3);}else if(!storageWarned){toast('Das Lager ist voll. Verarbeite Vorräte oder vergrößere den Lagerschuppen.');storageWarned=true;}}else storageWarned=false;
  for(const event of advanceProduction(state,simDt)){const w=WORKSHOPS.find(w=>w.id===event.id);floater(w.x,w.z,'+ 1 '+PRODUCTS[event.product].name,true);}
  for(const event of automation.update(state,cells,player,simDt,growthTime)){if(event.kind==='warehouseDelivery')scene.makeTransfer(event,VILLAGE.warehouse);if(event.kind==='woodcockFind'){floater(event.x,event.z,'Ein Waldschatz! ♧',true);farmHarvest+=FARM.findEvery;}if(event.kind==='woodcockDelivery')scene.makeTransfer(state.village.woodcock,{x:event.x,z:event.z});if(event.kind==='partnerSale'||event.kind==='woodcockSale'){scene.receiveMoney(player,event.value);floater(WORLD.bank.x,WORLD.bank.z,'+ '+format(event.value)+' ✧');sound('sale');}if(event.kind==='partnerCollect')floater(player.x,player.z,'Ich bringe das zum Lager ♡',true);}
  if(simDt){productPickupClock+=dt;for(const w of WORKSHOPS){if(!state.village.workshops[w.id].level)continue;
    const input=workshopSpot(w,'input'),output=workshopSpot(w,'output');
    if(Math.hypot(player.x-input.x,player.z-input.z)<1.3){const batch=deliverWorkshop(state,w,dt*24);if(batch.count&&productPickupClock>.2){scene.makeTransfer(player,input);productPickupClock=0;}}
    if(Math.hypot(player.x-output.x,player.z-output.z)<1.3&&productPickupClock>.35){const room=capacity(state)-state.bag-productCargoCount(state),batch=takeWorkshopGoods(state,w.product,Math.min(4,room));if(batch.count){scene.makeTransfer(output,null,w.product);productPickupClock=0;sound();floater(w.x,w.z,'+ '+precise(batch.count)+' '+PRODUCTS[w.product].name);}}
  }}
  if(simDt){advanceFarm(state,simDt);const found=discoverShell(state,farmHarvest,simDt);farmHarvest=0;if(found)toast('Ein Häuschen gefunden: '+found.name+'! In deiner Farm wartet ein Platz.',true);}
  updatePurchase(dt);updateBoutiqueEntry(simDt);
  uiClock+=dt;saveClock+=dt;checkClock+=dt;if(uiClock>.25){uiClock=0;syncUI();}if(saveClock>10){saveClock=0;save();}if(checkClock>2){checkClock=0;for(const a of checkAchievements(state))toast('Neue Erinnerung: '+a.name,true);}
  scene.setDestination(controls.target);scene.update(dt,{player,partner:automation.partner,bag:state.bag+productCargoCount(state),productID:Object.keys(state.productCargo.items).find(id=>state.productCargo.items[id]>0),coins:state.coins,growthTime,range:reach(state)/38,time:clock,moving:player.moving,snails:automation.snails,payingPad:activePad});updateLabels(dt);
}
let activePad=null,productPickupClock=0,farmHarvest=0;
function updatePurchase(dt){const radius=VILLAGE.buying.radius;activePad=pads.filter(p=>p.visible&&!p.max&&Math.hypot(player.x-p.x,player.z-p.z)<radius).sort((a,b)=>Math.hypot(player.x-a.x,player.z-a.z)-Math.hypot(player.x-b.x,player.z-b.z))[0]??null;
  if(completedPad){const p=pads.find(p=>p.id===completedPad);if(!p||Math.hypot(player.x-p.x,player.z-p.z)>radius+.45)completedPad='';}
  $('payStatus').hidden=!activePad||modal.open;if(!activePad){dwellingID='';padDwell=0;return;}const p=activePad;if(dwellingID!==p.id||player.moving||modal.open){dwellingID=p.id;padDwell=0;}else padDwell+=dt;
  if(padDwell>=VILLAGE.buying.dwellSeconds&&completedPad!==p.id&&!p.locked&&!player.moving&&!modal.open){const result=payBuild(state,p,dt);padEffectClock+=dt;if(result.paid>0&&padEffectClock>.22){padEffectClock=0;scene.spendMoney(player,p);}if(result.complete){completedPad=p.id;save();sound('build');scene.celebrate(p);toast(p.kind==='partner'?(state.village.partner?'Schnecki ist eingezogen! Zusammen wächst der Garten weiter.':p.label+' ist fertig. Euer Zuhause wächst.'):p.id==='snail'?'Eine kleine Schnecke grast jetzt euer Beet ab.':p.label+' ist bereit.',true);for(const name of discoverSeeds(state))toast('Im neuen Beet entdeckt: '+name+'!',true);refreshWorld(result.structural);if(p.id==='endDay')setTimeout(()=>openDayEnd(true),20);if(p.id==='bus')toast('Die Bushaltestelle ist fertig. Eure nächste Reise wartet auf ein späteres Update. ♡',true);}}
  const info=upgradeInfo(p);$('payIcon').textContent=info.icon;const paid=state.village.payments[p.id]??0;$('payTitle').textContent=p.label;$('payIcon').textContent=info.icon;$('payAmount').textContent=completedPad===p.id?'Fertig ✓':format(paid)+' / '+format(p.cost)+' ✧';$('payBar').style.width=(completedPad===p.id?100:Math.min(100,paid/p.cost*100))+'%';$('payHint').textContent=p.locked?p.reason:completedPad===p.id?'Kurz von der Fläche gehen, bevor du weiter aufrüstest.':player.moving?info.short+' · Zum Kaufen stehen bleiben.':state.coins<=0?'Gesammelte Anzahlungen bleiben für euch erhalten.':info.short+' · Sternenstaub fließt in den Ausbau.';
}
function eventActive(){return false;}
function place(el,p){el.hidden=!p.visible;if(p.visible){el.style.left=p.x+'px';el.style.top=p.y+'px';}}
function updateLabels(dt){place($('playerLabel'),scene.worldToScreen(player.x,2.25,player.z+.1));if(state.village.partner)place($('partnerLabel'),scene.worldToScreen(automation.partner.x,2.1,automation.partner.z));else $('partnerLabel').hidden=true;const bank=scene.worldToScreen(WORLD.bank.x,.5,WORLD.bank.z+3.3);place($('bankLabel'),{...bank,visible:bank.visible&&state.tutorial<3&&state.bag>0});if(state.bag+productCargoCount(state)){place($('stackCount'),scene.worldToScreen(player.x,1.4+stackLayers(state.bag+productCargoCount(state))*WORLD.stack.layerHeight,player.z-.4));$('stackCount').textContent=format(state.bag+productCargoCount(state));}else $('stackCount').hidden=true;for(let i=floaters.length-1;i>=0;i--){const f=floaters[i];f.life-=dt;f.y+=dt*1.5;const p=scene.worldToScreen(f.x,f.y,f.z);f.el.style.left=p.x+'px';f.el.style.top=p.y+'px';f.el.style.opacity=Math.min(1,f.life*2);if(f.life<=0){f.el.remove();floaters.splice(i,1);}}}
function frame(t){const dt=Math.min(.05,(t-lastFrame)/1000||.016);lastFrame=t;if(active){try{update(dt);}catch(e){console.error(e);$('gameError').hidden=false;active=false;}}requestAnimationFrame(frame);}
function syncUI(){syncRoundUI();const v=state.village;$('coins').textContent=format(state.coins);$('walletHint').textContent='Sternenstaub';$('stars').textContent=format(state.stars);$('bagCount').textContent=format(state.bag+productCargoCount(state))+' / '+format(capacity(state));$('bagBar').style.width=Math.min(100,(state.bag+productCargoCount(state))/capacity(state)*100)+'%';$('bagPanel').classList.toggle('full',state.bag+productCargoCount(state)>=capacity(state));$('bagTitle').textContent=productCargoCount(state)?'Ernte & fertige Produkte':'Dein Erntestapel';$('bagHint').textContent=isSelling?'Bündel für Bündel verkaufen …':state.bag>=capacity(state)?'Voll! Zum Verkauf oder ins Lager.':state.bag>0?format(state.bagValue)+' ✧ als Rohstoffe · verarbeitet mehr wert.':productCargoCount(state)?format(productCargoCount(state))+' fertige Produkte zum Verkaufen':'Lager '+format(stockCount(v))+' / '+format(storageCapacity(state));$('gardenLabel').textContent='Unser Garten';$('gardenSub').textContent='AUSBAUSTUFE '+gardenLevel(state)+' · '+v.beds.filter(Boolean).length+(v.beds.filter(Boolean).length===1?' BEET':' BEETE');$('playerLabel').textContent=state.names[0];$('partnerLabel').textContent=state.names[1];$('duoLabel').textContent=v.partner?state.names.join(' & '):'Dein kleines Gartenparadies.';$('journeyText').textContent=v.partner?'Zusammen wächst es leichter.':v.snails?v.snails+' fleißige Ernteschnecken helfen mit.':'Jedes Beet ein neuer kleiner Anfang.';const m=missionInfo(state);$('missionNumber').textContent=String(state.mission.index+1).padStart(2,'0');$('missionTitle').textContent=m.title;$('missionDesc').textContent=m.kind==='harvested'?`Sammelt ${format(m.target)} kleine Gartenschätze.`:m.desc;$('missionProgress').textContent=format(Math.min(m.progress,m.target))+' / '+format(m.target);$('missionBar').style.width=Math.min(100,m.progress/m.target*100)+'%';$('claimMission').disabled=!m.done;$('claimMission').textContent=(m.done?'Abholen · ':'+ ')+format(m.reward)+' ✧';$('shopDot').hidden=!getBuildPads(state,TOOLS).some(p=>!p.max&&!p.locked&&state.coins>=p.cost-p.paid);$('sound').setAttribute('aria-label',state.sound?'Klang ausschalten':'Klang einschalten');$('sound').style.color=state.sound?'#a087bf':'';$('eventPill').hidden=!eventActive();if(eventActive())$('eventPill').querySelector('b').textContent=Math.ceil(240-state.stats.playSeconds%240)+' s';if(modal.open&&modalView==='inventory')updateInventoryCounts();if(modal.open&&modalView==='farm')updateFarmCounts();}

function padButton(p,label='Zum Bauplatz ↗'){if(!p.visible)return '<p class="future-build">Wird später im Garten entdeckt.</p>';return `<button class="upgrade-button" data-pad="${p.id}" ${p.locked||p.max?'disabled':''}><span>${p.max?'Bereit ✓':p.locked?'Später':label}</span><b>${p.max?'':format(Math.max(0,p.cost-p.paid))+' ✧'}</b></button>`;}
function card(p,desc,detail=''){if(!p.visible)return '';return `<article class="upgrade-card"><div class="upgrade-head"><div class="upgrade-icon">${p.icon}</div><div><h3>${p.label}</h3><div class="upgrade-level">${p.level?'STUFE '+p.level:'NOCH NICHT GEBAUT'}</div></div></div>${p.kind==='workshop'?`<p class="upgrade-desc">${desc}</p>`:''}<p class="upgrade-explanation">${upgradeInfo(p).description}</p><p class="upgrade-detail">${p.locked?p.reason:detail}</p>${padButton(p,p.level?'Zum Upgradefeld ↗':'Zum Baufeld ↗')}</article>`;}
function openShop(tab=selectedTab){selectedTab=tab;const all=getBuildPads(state,TOOLS),v=state.village;let html=title('KLEINE SCHRITTE, GROSSE GÄRTEN','Eure Werkstatt.','Wähle eine Fläche zum Hinlaufen. Gekauft wird direkt im Garten: stehen bleiben, bezahlen, fertig.')+`<div class="modal-tabs" role="tablist" aria-label="Werkstatt"><button role="tab" data-tab="tools" aria-selected="${tab==='tools'}" class="${tab==='tools'?'active':''}">Werkzeuge</button><button role="tab" data-tab="helpers" aria-selected="${tab==='helpers'}" class="${tab==='helpers'?'active':''}">Schnecken & Hilfe</button><button role="tab" data-tab="production" aria-selected="${tab==='production'}" class="${tab==='production'?'active':''}">Produktion</button></div>`;
  if(tab==='tools')html+='<div class="shop-grid">'+TOOLS.map(t=>{const p=all.find(p=>p.id==='tool:'+t.id),next={...state,tools:{...state.tools,[t.id]:state.tools[t.id]+1}},detail=t.id==='bag'?format(capacity(state))+' → '+format(capacity(next))+' Plätze im Stapel':t.id==='reach'?precise(reach(state)/38)+' → '+precise(reach(next)/38)+' m Ernteradius':t.id==='speed'?Math.round(moveSpeed(state)/142*100)+' → '+Math.round(moveSpeed(next)/142*100)+' % Lauftempo':'+12 % Wert für neue Ernte und daraus hergestellte Produkte.';return card(p,t.desc,detail);}).join('')+'</div>';
  if(tab==='helpers')html+='<p class="shop-note">Schnecken grasen echte Pflanzen ab, tragen die Ernte ins Lager und schaffen Platz für die nächste Runde. Dein Lieblingsmensch zieht später ein und bringt fertige Produkte zum Verkauf.</p><div class="shop-grid">'+card(all.find(p=>p.id==='snail'),'Eine kleine Schnecke für die nächste Ernte.',v.snails+' Schnecken eingezogen.')+card(all.find(p=>p.id==='farm'),'Eine kleine Aufzucht für gefundene Häuschen.','Zehn Arten entdecken, füttern und als Helfer einsetzen oder verkaufen.')+card(all.find(p=>p.id==='woodcock'),'Eine Waldschnepfe für wählbare Aufträge.','Zutaten bringen, Waren verkaufen oder Waldschätze suchen.')+card(all.find(p=>p.id==='snailLevel'),'Flinker laufen, schneller grasen, mehr tragen.','Blattmütze ab Stufe 2 · Blumenkranz ab 4 · Erntewagen ab 6.')+card(all.find(p=>p.id==='partner'),'Holt volle Stapel ab und verkauft fertige Produkte.',all.find(p=>p.id==='partner').description+' · Bauabschnitt '+Math.min(3,v.house+1)+' / 3')+'</div>';
  if(tab==='production')html+='<p class="shop-note">Bringe passende Zutaten links an eine Werkstatt und hole rechts die fertigen Stapel ab. Erst mit Helfern wird das Lager zum gemeinsamen Nachschub. Nachts wird nur ein kleiner Teil vorhandener Zutaten verarbeitet. Später entsteht aus Sternentee + Blütenduftöl + Glühpilzen das Mondelixier: fertige Waren werden selbst wieder zu Zutaten.</p><div class="shop-grid">'+WORKSHOPS.map(w=>{const p=all.find(p=>p.id==='workshop:'+w.id);return card(p,w.description,`1 ${PRODUCTS[w.product].name} = ${format(productValue({...state,village:{...v,workshops:{...v.workshops,[w.id]:{...v.workshops[w.id],level:Math.max(1,v.workshops[w.id].level)}}}},w))} ✧ · ${w.seconds} s Grundzeit`);}).join('')+'</div>';
  openModal(html,'shop');modal.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>openShop(b.dataset.tab));}
function openBuildMenu(){const all=getBuildPads(state,TOOLS),v=state.village;let html=title('EUER EIGENES KLEINES ZUHAUSE','Ein Garten, der immer mehr kann.','Alle Ausbauten haben feste Plätze. Tippe auf eine Fläche, laufe hin und bleibe zum Kaufen darauf stehen.')+'<div class="building-list">';BEDS.forEach((b,i)=>{const p=all.find(p=>p.id==='bed:'+i);if(!p.visible)return;html+=`<article class="building-card"><h3>${b.name}</h3><p>${COLLECTIBLES[b.crop].plural} · ${p.level?'Stufe '+p.level:'Neues Beet'}<br>Jede Verbesserung: +40 % Erntewert und schnelleres Nachwachsen.</p>${padButton(p)}</article>`;});for(const id of ['farm','warehouse','sprinkler','partner','bus']){const p=all.find(p=>p.id===id);if(!p.visible)continue;html+=`<article class="building-card"><h3>${p.label}</h3><p>${id==='farm'?'Häuschen sammeln, kleine Schnecken füttern und aufziehen.':id==='warehouse'?'Mehr Platz für Rohstoffe.':id==='bus'?'Hier wird eure Reise später weitergehen. Die nächste Welt folgt in einem zukünftigen Update.':id==='sprinkler'?'Gesunde Erde lässt alle Beete schneller nachwachsen.':'Zieht später ein und automatisiert Transporte und Verkauf.'}</p><p class="upgrade-explanation">${upgradeInfo(p).icon} ${upgradeInfo(p).description}</p><p>${p.locked?p.reason:''}</p>${padButton(p)}</article>`;}for(const p of all.filter(p=>p.kind==='seed'&&p.visible&&!p.max))html+=card(p,'Ein Samen bleibt dauerhaft in eurer Sammlung.');html+='</div><button class="modal-action secondary" id="boutiqueOverview">Dekorationen & Accessoires</button><button class="modal-action secondary" id="productionOverview">Werkzeuge, Schnecken & Werkstätten</button>';openModal(html,'build');$('productionOverview').onclick=()=>openShop('tools');$('boutiqueOverview').onclick=openBoutiques;}
modal.addEventListener('click',e=>{const b=e.target.closest('[data-pad]');if(b&&!b.disabled)goPad(b.dataset.pad);});
$('shopButton').onclick=()=>openShop();$('gardensButton').onclick=openBuildMenu;$('openGardens').onclick=openBuildMenu;
function openInventory(){let html=title('VON DER BLUME ZUM KLEINEN SCHATZ','Eure Vorräte.','Am Anfang bringst du Zutaten direkt links zu den Werkstätten; rechts holst du fertige Stapel ab. Das Lager ist zusätzlicher Stauraum. Sobald Helfer einziehen, versorgt es die Werkstätten. Nachts wird mit 2,5 % Tempo für höchstens eine Stunde verarbeitet – ohne automatische Ernte oder Verkäufe.')+`<p class="warehouse-stat" id="warehouseSummary"></p><h3>Rohstoffe im Lager</h3>`;for(const [id,c]of Object.entries(COLLECTIBLES))html+=`<div class="stock-line"><span>${c.plural}</span><b data-stock="raw:${id}">0</b></div>`;html+='<h3 style="margin-top:20px">Fertige Produkte an den Werkstätten</h3>';for(const [id,p]of Object.entries(PRODUCTS))html+=`<div class="stock-line"><span>${p.plural}</span><b data-stock="finished:${id}">0</b></div>`;html+='<h3 style="margin-top:20px">Werkstätten</h3>';for(const w of WORKSHOPS)html+=`<div class="stock-line"><span>${w.name}</span><b data-machine="${w.id}"></b></div>`;if(state.village.woodcock.unlocked)html+='<h3>Waldschnepfe beauftragen</h3><p id="woodcockTreasures"></p>'+Object.entries(WOODCOCK_TASKS).map(([id,label])=>`<button class="modal-action secondary" data-bird-task="${id}" aria-pressed="${state.village.woodcock.task===id}">${state.village.woodcock.task===id?'✓ ':''}${label}</button>`).join('');if(state.village.farm.built)html+='<button class="modal-action" id="openFarm">Schneckenfarm öffnen ꩜</button>';html+='<h3>Zutaten direkt abliefern</h3>'+WORKSHOPS.filter(w=>state.village.workshops[w.id].level).map(w=>`<button class="modal-action secondary" data-deliver="${w.id}">Zu ${w.name} ↗</button>`).join('');html+='<button class="modal-action secondary" id="withdrawRaw">Rohstoffe aus dem Lager abholen ↗</button><button class="modal-action" id="pickProducts">Fertige Produkte an der Werkstatt abholen ↗</button><button class="modal-action" id="stockDeposit">Ernte ins Lager bringen ↗</button><button class="modal-action secondary" id="stockSell">Zum Verkauf fertiger Produkte ↗</button>';openModal(html,'inventory');if($('openFarm'))$('openFarm').onclick=openFarm;modal.querySelectorAll('[data-bird-task]').forEach(b=>b.onclick=()=>{state.village.woodcock.task=b.dataset.birdTask;state.village.woodcock.timer=0;save();openInventory();});modal.querySelectorAll('[data-deliver]').forEach(b=>b.onclick=()=>walkTo(workshopSpot(WORKSHOPS.find(w=>w.id===b.dataset.deliver),'input')));$('withdrawRaw').onclick=()=>{collectingRaw=true;goWarehouse();};$('pickProducts').onclick=()=>{const w=WORKSHOPS.find(w=>(state.village.finished[w.product]??0)>0);if(w)walkTo(workshopSpot(w,'output'));else toast('Die Werkstätten haben noch keine fertigen Produkte.');};$('stockDeposit').onclick=goWarehouse;$('stockSell').onclick=goBank;updateInventoryCounts();}
function updateInventoryCounts(){if(!$('warehouseSummary'))return;const v=state.village;if($('woodcockTreasures'))$('woodcockTreasures').textContent=v.woodcock.treasures+' Waldschätze gesammelt · Auftrag: '+WOODCOCK_TASKS[v.woodcock.task];$('warehouseSummary').textContent=format(stockCount(v))+' / '+format(storageCapacity(state))+' Lagerplätze · '+format(v.produced)+' Produkte hergestellt · '+format(v.autoSold)+' automatisch verkauft';for(const el of modal.querySelectorAll('[data-stock]')){const [group,id]=el.dataset.stock.split(':');el.textContent=precise(v[group][id]??0);}for(const el of modal.querySelectorAll('[data-machine]')){const w=WORKSHOPS.find(w=>w.id===el.dataset.machine),m=v.workshops[w.id];el.textContent=!m.level?'Noch nicht gebaut':(m.running?'Arbeitet · '+Math.min(100,Math.floor(m.progress/productionSeconds(state,w)*100))+' %':(v.finished[w.product]??0)>=24?'Abholstapel voll':'Wartet auf Zutaten')+' · '+precise(workshopStock(m))+' Zutaten vor Ort';}}
$('travelButton').onclick=openInventory;$('stockShortcut').onclick=openInventory;
function openFarm(){const f=state.village.farm;if(!f.built)return;let html=title('KLEINE HÄUSCHEN, GROSSE FREUNDE','Deine Schneckenfarm.','Setze gefundene Häuschen in die Farm. Drei Mahlzeiten und zwölf Minuten Wachstum machen eine Schnecke groß. Hungrige Schnecken warten einfach auf dich.')+'<p id="farmSummary"></p><h3>Schneckenfutter herstellen</h3><button class="modal-action secondary" data-food="flowers">12 Mondblüten → 2 Portionen</button>'+(state.village.beds[4]?'<button class="modal-action secondary" data-food="fruit">6 Mondblüten + 2 Sternenfrüchte → 4 Portionen</button>':'')+'<p class="shop-note">Zutaten werden aus deinem Stapel oder dem Lager genommen. Eine Portion reicht für vier Minuten. Die Kleinen wachsen auch, während du die Farm ansiehst.</p><h3>Gefundene Häuschen</h3>';
for(const n of SNAILS)if(f.discovered.includes(n.id))html+=`<button class="modal-action secondary" data-shell="${n.id}" ${!f.shells[n.id]||f.nursery.length>=FARM.slots?'disabled':''}>${esc(n.name)} · ${f.shells[n.id]??0} Häuschen · Einsetzen</button>`;
if(!f.discovered.length)html+='<p>Beim Ernten findest du gelegentlich ein Häuschen. Später hilft auch die Waldschnepfe beim Suchen.</p>';
html+='<h3>Aufzucht</h3>';for(const n of f.nursery){const kind=SNAILS.find(k=>k.id===n.species),grown=n.growth>=FARM.growSeconds;html+=`<article class="upgrade-card"><h3>${esc(kind.name)}</h3><p data-snail="${n.id}" data-care="${grown?'adult':n.meal>0?'fed':'hungry'}"></p>${grown?`<button class="modal-action" data-snail-helper="${n.id}" ${state.village.snails>=farmHelperLimit(state)?'disabled':''}>Als Helfer einsetzen</button><button class="modal-action secondary" data-snail-sell="${n.id}">Verkaufen</button>`:`<button class="modal-action secondary" data-snail-feed="${n.id}" ${n.meal>0||!f.food?'disabled':''}>Eine Portion füttern</button>`}</article>`;}
html+='<button class="modal-action secondary" id="farmBack">Zurück zur Verwaltung</button>';openModal(html,'farm');updateFarmCounts();$('farmBack').onclick=openInventory;
const bind=(selector,action)=>modal.querySelectorAll(selector).forEach(b=>b.onclick=()=>{const before=state.village.snails;if(!action(b))toast('Dafür fehlen Zutaten, Futter oder ein freier Platz.');if(state.village.snails!==before)refreshWorld(false);save();openFarm();});
bind('[data-food]',b=>makeSnailFood(state,b.dataset.food));bind('[data-shell]',b=>moveShellToFarm(state,b.dataset.shell));bind('[data-snail-feed]',b=>feedSnail(state,Number(b.dataset.snailFeed)));bind('[data-snail-helper]',b=>releaseSnail(state,Number(b.dataset.snailHelper),'helper'));bind('[data-snail-sell]',b=>releaseSnail(state,Number(b.dataset.snailSell),'sell'));}
function updateFarmCounts(){const f=state.village.farm;if(!$('farmSummary'))return;$('farmSummary').textContent=f.nursery.length+' / '+FARM.slots+' Aufzuchtplätze · '+f.food+' Portionen · '+state.village.snails+' / '+farmHelperLimit(state)+' Helferplätze (höchstens zwölf) · '+f.discovered.length+' / 10 Arten entdeckt';for(const el of modal.querySelectorAll('[data-snail]')){const n=f.nursery.find(n=>n.id===Number(el.dataset.snail));if(!n){openFarm();return;}const care=n.growth>=FARM.growSeconds?'adult':n.meal>0?'fed':'hungry';if(el.dataset.care!==care){openFarm();return;}el.textContent=Math.floor(n.growth/FARM.growSeconds*100)+' % aufgezogen · '+(n.growth>=FARM.growSeconds?'Erwachsen':n.meal>0?Math.ceil(n.meal/60)+' min Futter übrig':'Möchte Futter');}}
function openNames(){openModal(title('EIN GARTEN FÜR EUCH','Wer zieht hier seine Bahnen?','Schnecki zieht nach dem dritten Hausbauabschnitt ein und übernimmt Transporte und Verkauf.')+`<form id="nameForm"><label class="field">Deine Figur<input id="nameOne" maxlength="24" required value="${esc(state.names[0])}" autocomplete="off"></label><label class="field">Dein Lieblingsmensch<input id="nameTwo" maxlength="24" required value="${esc(state.names[1])}" autocomplete="off"></label><button class="modal-action" type="submit">Das sind wir ✳</button></form>`,'names');$('nameForm').onsubmit=e=>{e.preventDefault();state.names=[$('nameOne').value.trim()||'Du',$('nameTwo').value.trim()||'Schnecki'];save();syncUI();closeModal();};}
$('customize').onclick=openNames;
function openJournal(){openModal(title('EURE KLEINEN GROSSEN MOMENTE','Erinnerungsbuch.',state.achievements.length+' von '+ACHIEVEMENTS.length+' Erinnerungen gesammelt.')+ACHIEVEMENTS.map(a=>`<div class="achievement ${state.achievements.includes(a.id)?'unlocked':''}"><span>${state.achievements.includes(a.id)?'✦':'☆'}</span><div><strong>${a.name}</strong><small>${a.desc}</small></div></div>`).join(''),'journal');}
function openSettings(){openModal(title('MACHT ES EUCH GEMÜTLICH','Euer Garten, euer Tempo.','Finger auf eine freie Stelle setzen und ziehen: Dort erscheint dein Joystick. Auch WASD und Pfeiltasten bewegen dich. Leertaste führt zum Verkauf. Auf ↑-Flächen stehen bleiben, um zu bauen und aufzurüsten.')+`<div class="settings-row"><button class="modal-action secondary" id="toggleSound">Klang ${state.sound?'aus':'an'}</button><button class="modal-action secondary" id="toggleMotion">${state.reducedMotion?'Mehr':'Weniger'} Bewegung</button></div><button class="modal-action secondary" id="editNames">Eure Namen ändern</button><button class="modal-action secondary" id="journal">Erinnerungsbuch · ${state.achievements.length} / ${ACHIEVEMENTS.length}</button><button class="modal-action secondary" id="roundSettings">${embedded?'Gartenrunden':'Gartenrunden & Vorschau'}</button><button class="modal-action secondary" id="settingsStock">Lager und Werkstätten</button><div class="settings-row"><button class="modal-action secondary" id="exportSave">Spielstand sichern ↓</button><button class="modal-action secondary" id="importSave">Sicherung laden ↑</button></div><input class="file-input" id="saveFile" type="file" accept=".json,application/json"><p class="shop-note">Automatisch alle 10 Sekunden auf diesem Gerät gespeichert. Nach 30 aktiven Minuten schläfst du ein; Menüs und Pausen zählen nicht mit. Warnungen erscheinen drei Minuten und eine Minute vorher. Nachts verarbeiten Werkstätten vorhandene Zutaten mit 2,5 % Tempo für höchstens eine Stunde. Es wird dabei nichts geerntet oder verkauft. Im Garten kannst du auch nach dem Tagesabschluss weiter sammeln; Pflanzen wachsen allmählich langsamer nach.</p><button class="modal-action secondary" id="help">Wie funktioniert der Garten?</button><button class="modal-action danger" id="resetGame">Ganz von vorne anfangen</button>`,'settings');
  $('toggleSound').onclick=()=>{state.sound=!state.sound;sound('build');save();syncUI();openSettings();};$('toggleMotion').onclick=()=>{state.reducedMotion=!state.reducedMotion;document.body.classList.toggle('reduced-motion',state.reducedMotion);save();openSettings();};$('editNames').onclick=openNames;$('journal').onclick=openJournal;$('settingsStock').onclick=openInventory;$('roundSettings').onclick=openRounds;
  $('exportSave').onclick=()=>{save();const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='mondgarten-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Eure Gartengeschichte wurde gesichert.');};
  $('importSave').onclick=()=>$('saveFile').click();$('saveFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>1000000)throw new Error('Die Datei ist zu groß.');const imported=normalize(JSON.parse(await file.text()));openModal(title('EINE GESPEICHERTE GESCHICHTE','Diesen Garten laden?',`${esc(imported.names.join(' & '))} · Ausbaustufe ${gardenLevel(imported)} · ${format(imported.coins)} ✧`)+`<p>Der aktuelle Spielstand auf diesem Gerät wird durch diese Sicherung ersetzt.</p><button class="modal-action" id="confirmImport">Sicherung übernehmen</button><button class="modal-action secondary" id="cancelImport">Abbrechen</button>`,'import');$('cancelImport').onclick=openSettings;$('confirmImport').onclick=()=>{state=imported;offlineEarnings(state);resetWorld();tutorial(state.tutorial);document.body.classList.toggle('reduced-motion',state.reducedMotion);save();closeModal();toast('Euer Garten ist wieder da.');};}catch(e){toast('Diese Sicherung konnte nicht geladen werden. '+e.message);}};
  $('help').onclick=()=>{openModal(title('ALLES WÄCHST ZUSAMMEN','Vom kleinen Beet zum Gartenparadies.','Ernte Blumen und verkaufe sie zunächst als Rohstoffe. Kaufe auf den markierten Bodenflächen eine bessere Sichel, mehr Platz und weitere Beete.')+`<p>Baue die Blumenbinderei, bringe Mondblüten links an ihren Tisch, hole rechts fertige Sträuße ab und verkaufe sie am Stand. Die Sternenteeküche verarbeitet Lavendel, die Destille Korallenblüten. Die Mondalchemie braucht später Sternentee, Duftöl und Glühpilze.</p><p>Schnecken ernten selbst und bringen ihre Bündel ins Lager. Baue Fundament, Wände und Dach von Schneckis Zuhause. Beim Einzug übernimmt Schnecki die Transporte und den Verkauf. So wird der Garten nach und nach selbstständig.</p><p>Du erntest mit 25 % Zusatzwert. Bessere Beete erhöhen den Ertrag, Gartenpflege beschleunigt das Nachwachsen und bessere Werkstätten produzieren schneller und wertvoller.</p><p>Auf Kauf-Flächen wird der Preis nach kurzem Stillstehen nach und nach bezahlt. Anzahlungen bleiben erhalten. Verlasse die Fläche nach einem Kauf kurz, bevor du eine weitere Stufe kaufst.</p><button class="modal-action" id="backToGarden">Zurück in meinen Garten</button>`,'help');$('backToGarden').onclick=closeModal;};
  $('resetGame').onclick=()=>{openModal(title('EIN GANZ NEUES BLATT','Wirklich neu anfangen?','Beete, Werkstätten, Schnecken, Vorräte und Verbesserungen auf diesem Gerät werden gelöscht. Sichere deinen Spielstand vorher, wenn du ihn behalten möchtest.')+'<button class="modal-action danger" id="confirmReset">Ja, diesen Spielstand löschen</button><button class="modal-action secondary" id="cancelReset">Meinen Garten behalten</button>','reset');$('cancelReset').onclick=openSettings;$('confirmReset').onclick=()=>{state=embedded?prepareHostedState(freshState()):freshState();if(embedded)syncCompanionActions(state,JSON.parse(localStorage.getItem(COMPANION.journalKey)||'null'));clock=0;document.body.classList.remove('reduced-motion');resetWorld();tutorial(0);save();closeModal();};};
}
$('settings').onclick=openSettings;$('sound').onclick=()=>{state.sound=!state.sound;sound('build');save();syncUI();};$('closeModal').onclick=closeModal;modal.addEventListener('close',()=>modalView='');modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});document.querySelector('.brand').onclick=e=>{e.preventDefault();closeModal();};
document.addEventListener('visibilitychange',()=>{if(document.hidden){save();active=false;controls?.stop();}else{const result=offlineEarnings(state);lastFrame=performance.now();active=!!scene;if(result.amount>1||result.produced>0)toast('Während deiner Pause: '+format(result.produced)+' Produkte · '+format(result.amount)+' ✧ verkauft.',true);automation=new GardenAutomation(state);syncUI();}});window.addEventListener('pagehide',save);
try{validateContent();scene=new GardenScene($('world'),{reducedMotion:reduced});controls=new GardenControls($('world'),$('joystick'),scene,{blocked:()=>modal.open||hostedFinishPending||state.journey.asleep,onBank:goBank});resetWorld();tutorial(state.tutorial);document.body.classList.toggle('reduced-motion',state.reducedMotion);requestAnimationFrame(frame);$('loading').classList.add('done');setTimeout(()=>$('loading').remove(),500);}catch(e){console.error(e);$('loading').hidden=true;$('gameError').hidden=false;}
if(state.journey.asleep)setTimeout(openSleep,700);
if(!state.journey.asleep&&(offline.amount>1||offline.produced>0))setTimeout(()=>{if(state.journey.asleep)return;openModal(title('WILLKOMMEN ZURÜCK','Der Garten war fleißig.',`${format(offline.seconds/60)} Minuten Pause · ${format(offline.produced)} Produkte hergestellt.`)+`<div class="travel-summary">Automatisch verkauft: <b>${format(offline.amount)} ✧</b><br>${'Deine fertigen Produkte warten an den Werkstätten. Während der Pause wird nichts verkauft.'}</div><button class="modal-action" id="backToGarden">Wieder im Garten ankommen</button>`,'offline');$('backToGarden').onclick=closeModal;},700);save();

function syncRoundUI(){const j=state.journey,f=growthFactor(state);$('dayChip').textContent=(j.asleep?'☾ Zz ':j.closed?'☾ ':f<.7?'◔ ':'☀ ')+'Tag '+j.round;$('dayChip').classList.toggle('resting',j.closed||f===0);$('dayGoal').textContent=j.asleep&&j.sleepMissed?'Ohne Tagesbelohnung':j.closed?'Tagesbelohnung ✓':'Tagesbelohnung ↗';$('roundNumber').textContent='Gartentag '+j.round;$('roundMood').textContent=!j.asleep&&j.elapsed>=DAY_RHYTHM.warning?'Du wirst müde · noch '+Math.ceil((DAY_RHYTHM.sleep-j.elapsed)/60)+' Minuten':j.asleep?'Du schläfst · Dieser Gartentag ist vorbei':j.closed?'Ein schöner Gartentag geht zu Ende':f===0?'Die Beete ruhen':f<.2?'Der Garten wird still':f<.7?'Die Beete werden müde':'Ein Garten voller Möglichkeiten';$('roundNote').textContent=j.pending?j.pending+' verdiente Runde'+(j.pending===1?'':'n')+' wartet':j.preview?'Eigenständige Vorschau · Begleit-App noch nicht verbunden':'Ein neuer Eintrag schenkt die nächste Runde';$('roundProgress').style.width=Math.min(100,j.elapsed/DAY_RHYTHM.sleep*100)+'%';$('nextRound').hidden=embedded||!j.pending||!j.closed;$('roundWidget').classList.toggle('resting',f===0);}
function enterNextRound(){if(!startRound(state))return;prepareDay(state,TOOLS);for(const name of discoverSeeds(state))toast('Ein Samen wurde beim Beet gefunden: '+name+'!',true);refreshWorld(false);save();closeModal();toast('Gartentag '+state.journey.round+(state.journey.round<=77?' · Neues Wachstum und +5,5 % Erntewert.':' · Dein Garten erwacht wieder.'),true);sound('build');scene.celebrate(player);}
function openRounds(){const j=state.journey;openModal(title('EIN KLEINER GARTENMOMENT','Deine Gartenrunden.', 'Gartentag '+j.round+' · '+j.pending+' weitere Runden gesammelt.')+'<p>Du wählst deine Ausbauten frei. Neue Runden öffnen nach und nach weitere Stufen und Möglichkeiten. Für alle heute angebotenen Ausbaustufen und die Gartenaktion ist genügend Ertrag möglich. Du darfst weiter sammeln: Je länger du spielst, desto langsamer wachsen Pflanzen nach. Vorhandene Zutaten, Produkte und Geld bleiben erhalten.</p><p>Ein bestätigter neuer Eintrag auf der Begleitseite schenkt eine Runde. Danach gilt eine Pause von zehn Minuten für Eintragsbelohnungen. Gießen lässt dort deine Pflanzen wachsen.</p><button class="modal-action" id="useRound" '+(embedded||!j.pending||!j.closed?'disabled':'')+'>Gesammelte Runde beginnen</button>'+(j.preview?'<div class="preview-note"><strong>Eigenständige Spielvorschau</strong><p>Die Begleit-App ist noch nicht verbunden. Dieser Testknopf simuliert eine verdiente Runde.</p><button class="modal-action secondary" id="previewRound" '+(j.round+j.pending>=10000?'disabled':'')+'>Vorschau: eine Gartenrunde erhalten</button></div>':'')+'<p class="shop-note">Kaufe die Tagesbelohnung vor dem Einschlafen: Nach 30 aktiven Minuten endet jeder Gartentag. Bei einer verpassten Belohnung verlierst du keine Vorräte; fehlende Samen und Gießaktionen bleiben an späteren verdienten Tagen erhältlich. Schneckis Haus braucht drei Bauabschnitte und selbst hergestellte Produkte.</p>','rounds');$('useRound').onclick=enterNextRound;if($('previewRound'))$('previewRound').onclick=()=>{if(grantRound(state,'preview:'+String(j.round+j.pending+1))){save();openRounds();}};}
$('roundWidget').onclick=e=>{if(!e.target.closest('#nextRound')&&!e.target.closest('#dayGoal'))openRounds();};$('nextRound').onclick=enterNextRound;

function openDayGoal(){if(state.journey.asleep){openSleep();return;}if(state.journey.closed){openDayEnd();return;}const p=getBuildPads(state,TOOLS).find(p=>p.id==='endDay'),kind=state.journey.rewardKind;if(kind==='rest'){openModal(title('EIN RUHIGER FEIERABEND','Gartenpause.','Deine Pflanzenbelohnungen sind vollständig gesammelt. Du kannst den Garten in weiteren verdienten Runden fertig ausbauen.')+'<p>Dieser Tagesabschluss vergibt keine zusätzliche Gießaktion und keinen weiteren Samen.</p>'+padButton(p,'Zum Tagesabschluss ↗'),'day-goal');return;}openModal(title('DEIN KLEINER FEIERABEND','Was wächst in der Begleit-App weiter?','Sichere eine Gießaktion oder einen Samen. Der Kauf beendet diesen Gartentag.')+'<div class="reward-choice"><button id="chooseWater" class="'+(kind==='water'?'selected':'')+'" '+(rewardCount(state,'water')>=70?'disabled':'')+'>☂ Gießkanne</button><button id="chooseSeed" class="'+(kind==='seed'?'selected':'')+'" '+(rewardCount(state,'seed')>=7?'disabled':'')+'>✧ Samen</button></div><p>Bis zum Abschluss kannst du dein Geld frei für Ausbauten verwenden oder auf größere Wünsche sparen.</p><div class="reward-grid"><div>Gießaktionen<strong>'+rewardCount(state,'water')+'</strong></div><div>Samen<strong>'+rewardCount(state,'seed')+'</strong></div></div><p class="shop-note">'+(embedded?'Danach kannst du im Garten bleiben oder zur Begleitseite zurückgehen und deine Pflanzen versorgen.':'Vorschau: Belohnungen werden hier gespeichert.')+'</p>'+padButton(p,'Zum Tagesabschluss ↗'),'day-goal');$('chooseWater').onclick=()=>{state.journey.rewardKind='water';refreshWorld(false);save();openDayGoal();};$('chooseSeed').onclick=()=>{state.journey.rewardKind='seed';refreshWorld(false);save();openDayGoal();};}
function openDayEnd(justFinished=false){if(state.journey.asleep){openSleep();return;}const j=state.journey;openModal(title('GUT GEMACHT FÜR HEUTE','Ein kleines Stück weiter.',j.rewardKind==='rest'?'Dein Garten kann jetzt ausruhen.':(j.rewardKind==='seed'?'Ein Samen':'Eine Gießaktion')+' wurde als Belohnung vorgemerkt.')+'<p>Du kannst noch durch den Garten laufen, ernten, Zutaten abliefern und Stapel verkaufen. Nach insgesamt 30 aktiven Minuten schläfst du ein. Pflanzen wachsen mit der Zeit langsamer nach. Neue Ausbauten warten auf die nächste verdiente Runde.</p><div class="reward-grid"><div>Gießaktionen<strong>'+rewardCount(state,'water')+'</strong></div><div>Samen<strong>'+rewardCount(state,'seed')+'</strong></div></div><p class="shop-note">'+(embedded?'Deine Belohnung kannst du direkt auf der Begleitseite einpflanzen oder auf eine Pflanze gießen.':'Die Belohnung bleibt in dieser eigenständigen Vorschau gespeichert.')+'</p><button class="modal-action" id="nightGarden">Noch ein bisschen im Garten bleiben</button><button class="modal-action secondary" id="dayRounds">Gartenrunden ansehen</button>'+(embedded?'<button class="modal-action" id="returnPlants">Zurück zu meinen Pflanzen</button>':''),'day-end');$('nightGarden').onclick=closeModal;$('dayRounds').onclick=openRounds;if($('returnPlants'))$('returnPlants').onclick=finishHostedDay;}
$('dayGoal').onclick=e=>{e.stopPropagation();openDayGoal();};



function openGardenMenu(){openModal(title('DEIN KLEINER RÜCKZUGSORT','Mondgarten.','Gartentag '+state.journey.round)+`<div class="menu-route"><button class="modal-action secondary" id="menuSell">Verkaufen ↗</button><button class="modal-action secondary" id="menuStore">Ins Lager ↗</button></div><div class="garden-menu"><button id="menuGoal"><span>☾</span><div><strong>Tagesbelohnung</strong><small>Gießaktion oder Samen sichern</small></div></button><button id="menuBuild"><span>❀</span><div><strong>Garten ausbauen</strong><small>Beete, Werkzeuge & kleine Helfer</small></div></button><button id="menuStock"><span>▤</span><div><strong>Vorräte & Produktion</strong><small>Zutaten und fertige Produkte</small></div></button><button id="menuBoutiques"><span>✿</span><div><strong>Dekoration & Kleidung</strong><small>Dauerhafte Läden und kleine Wünsche</small></div></button><button id="menuSettings"><span>⚙</span><div><strong>Einstellungen</strong><small>Klang, Namen & Spielstand</small></div></button></div>`,'garden-menu');$('menuSell').onclick=goBank;$('menuStore').onclick=goWarehouse;$('menuGoal').onclick=openDayGoal;$('menuBuild').onclick=openBuildMenu;$('menuStock').onclick=openInventory;$('menuSettings').onclick=openSettings;$('menuBoutiques').onclick=openBoutiques;}
$('gardenMenu').onclick=openGardenMenu;$('dayChip').onclick=openDayGoal;

if(embedded){window.addEventListener('storage',e=>{if(e.key!==COMPANION.journalKey)return;try{if(syncCompanionActions(state,JSON.parse(e.newValue||'null'))){prepareDay(state,TOOLS);refreshWorld(false);save();toast('Ein verdienter Gartentag wartet auf dich.');}}catch{}});window.addEventListener('message',e=>{if(e.origin===location.origin&&e.source===parent&&e.data?.type==='mondgarten:save'){controls?.stop();save();}if(e.origin===location.origin&&e.source===parent&&e.data?.type==='mondgarten:start'){if(state.journey.closed&&state.journey.pending)enterNextRound();}});}

let hostedFinishPending=false;
function finishHostedDay(){
 if(hostedFinishPending)return;const missed=state.journey.asleep&&state.journey.sleepMissed;hostedFinishPending=true;controls?.stop();closeModal();save();
 const cover=document.createElement('div');cover.className='hosted-day-finish';cover.setAttribute('role','status');
 const symbol=document.createElement('span'),text=document.createElement('strong'),note=document.createElement('p');symbol.textContent=state.journey.rewardKind==='water'?'☂':'❀';text.textContent=missed?'Der Garten ruht.':'Ein schöner Gartentag geht zu Ende.';note.textContent=missed?'Beim nächsten verdienten Gartentag geht es weiter.':state.journey.rewardKind==='water'?'Deine Gießkanne wartet bei deinen Pflanzen.':state.journey.rewardKind==='seed'?'Ein neuer Samen wartet auf sein Plätzchen.':'Zurück zu deinen Pflanzen.';cover.append(symbol,text,note);document.body.append(cover);
 setTimeout(()=>{save();parent.postMessage({type:'mondgarten:day-ended',round:state.journey.round,kind:missed?'rest':state.journey.rewardKind},location.origin);},state.reducedMotion||matchMedia('(prefers-reduced-motion: reduce)').matches?350:1900);
}

function openBoutiques(){
 const b=state.village.boutiques;
 let html=title('KLEINE WÜNSCHE BLEIBEN','Eure Gartenläden.','Teurere Läden baut ihr einmal. Danach könnt ihr immer wieder etwas für Deko oder Accessoires einzahlen. Jede Anzahlung bleibt über Tage und Pausen erhalten. Alles ist freiwillig und verändert eure Erträge nicht.');
 const funding=(d,construction=false)=>{const paid=b.payments[d.id]??0,cost=cosmeticPrice(d.id),locked=state.journey.round<d.round;return `<article class="upgrade-card"><h3>${esc(d.name)}${construction?' · Laden bauen':''}</h3><p>${esc(d.description)}</p><p>${locked?'Ab Gartentag '+d.round:format(paid)+' / '+format(cost)+' ✧ angespart'}</p>${locked?'':`<progress max="${cost}" value="${paid}" aria-label="${esc(d.name)} angespart"></progress><div class="settings-row">${[100,1000].map(n=>`<button class="modal-action secondary" data-cosmetic="${d.id}" data-amount="${n}" ${state.coins<=0?'disabled':''}>Bis zu ${format(n)} ✧</button>`).join('')}</div><button class="modal-action secondary" data-cosmetic="${d.id}" data-amount="${cost-paid}" ${state.coins<=0?'disabled':''}>Rest einzahlen · ${format(cost-paid)} ✧</button>`}</article>`;};
 for(const shop of BOUTIQUES){if(!b.built.includes(shop.id)){html+=funding(shop,true);continue;}html+='<h3>'+esc(shop.name)+' · Gebaut ✓</h3>';for(const d of COSMETICS.filter(d=>d.shop===shop.id)){if(!b.owned.includes(d.id)){html+=funding(d);continue;}html+=`<article class="upgrade-card"><h3>${esc(d.name)} ✓</h3><p>${esc(d.description)}</p>${d.shop==='decor'?'<p>Steht in eurem Garten.</p>':[0,1].map(i=>`<button class="modal-action secondary" data-equip="${d.id}" data-actor="${i}">${esc(state.names[i])}: ${b.equipped[i]===d.id?'Ablegen':'Anziehen'}</button>`).join('')}</article>`;}}
 openModal(html,'boutiques');
 modal.querySelectorAll('[data-cosmetic]').forEach(el=>el.onclick=()=>{const result=contributeCosmetic(state,el.dataset.cosmetic,Number(el.dataset.amount));if(result.paid){refreshWorld(false);save();if(result.complete){sound('build');toast('Ein Wunsch ist fertig: '+[...BOUTIQUES,...COSMETICS].find(d=>d.id===el.dataset.cosmetic).name,true);}openBoutiques();}});
 modal.querySelectorAll('[data-equip]').forEach(el=>el.onclick=()=>{const actor=Number(el.dataset.actor),id=el.dataset.equip;equipCosmetic(state,actor,b.equipped[actor]===id?null:id);save();openBoutiques();});
}

function openSleep(){
 const j=state.journey;if(!j.asleep)return;
 const note=j.rewardKind==='rest'&&!j.sleepMissed?'Dieser Gartentag ist abgeschlossen. Alle Pflanzenbelohnungen sind bereits gesammelt.':j.sleepMissed?'Heute bist du vor dem Kauf eingeschlafen. Für diesen Gartentag gibt es keine neue Pflanzenbelohnung. Fehlende Belohnungen kannst du an späteren verdienten Tagen kaufen.':'Deine gekaufte Pflanzenbelohnung bleibt erhalten.';
 openModal(title('GUTE NACHT, KLEINER GARTEN','Einfach eingekuschelt.',note)+'<p>Geld, Waren, Baufortschritt und Anzahlungen sind sicher. Eine angefangene Zahlung für die Tagesbelohnung wurde zurückgegeben. Eine neue verdiente Runde weckt dich wieder.</p>'+(embedded?'<button class="modal-action" id="sleepReturn">Zur Begleitseite</button>':'')+'<button class="modal-action secondary" id="sleepRounds">Gartenrunden ansehen</button><button class="modal-action secondary" id="sleepSettings">Einstellungen & Sicherung</button>','sleep');
 if($('sleepReturn'))$('sleepReturn').onclick=finishHostedDay;$('sleepRounds').onclick=openRounds;$('sleepSettings').onclick=openSettings;
}

let boutiqueVisit=null,boutiqueDwell=0;
function updateBoutiqueEntry(dt){
 const shop=BOUTIQUES.find(d=>state.journey.round>=d.round&&Math.hypot(player.x-d.x,player.z-(d.z+1.8))<1.25);
 if(!shop){boutiqueVisit=null;boutiqueDwell=0;return;}
 if(!dt||player.moving||boutiqueVisit===shop.id){boutiqueDwell=0;return;}
 boutiqueDwell+=dt;if(boutiqueDwell>=.8){boutiqueVisit=shop.id;boutiqueDwell=0;openBoutiques();}
}
